$board=new AdmissionVotes($db,'s');$board->grant('v1',0,'1. Vorstand',true,true);$board->grant('v2',0,'2. Vorstand',true,true);$intake=new MembershipApplications($db,'a','s');$cfg=$intake->settings()['config'];$cfg['enabled']=true;$intake->saveSettings($cfg,0);$a=['first_name'=>'Test','last_name'=>'Antrag','email'=>'test@example.invalid','birthday'=>'1990-01-02','address'=>'Testweg'];$key=bin2hex(random_bytes(16));$id=$intake->submit($a,$key,1,true);$intake->submit($a,$key,1,true);ok((int)$db->query('SELECT COUNT(*) FROM application_notifications')->fetchColumn()===1,'same address and repeated request enqueue once');
